from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")


def invoice_total(lines, discount="0", tax="0"):
    discount = Decimal(discount)
    tax = Decimal(tax)
    if not Decimal("0") <= discount <= Decimal("1") or tax < 0:
        raise ValueError("invalid discount or tax")
    subtotal = Decimal("0")
    for unit_price, quantity in lines:
        price = Decimal(unit_price)
        if price < 0 or not isinstance(quantity, int) or quantity < 0:
            raise ValueError("invalid line item")
        subtotal += (price * quantity).quantize(CENT, rounding=ROUND_HALF_UP)
    total = subtotal * (Decimal("1") - discount) * (Decimal("1") + tax)
    return total.quantize(CENT, rounding=ROUND_HALF_UP)

