import unittest
from decimal import Decimal
from solution import invoice_total

class VisibleTests(unittest.TestCase):
    def test_exact_prices_and_quantities(self):
        self.assertEqual(invoice_total([("12.30", 2), ("1.10", 3)]), Decimal("27.90"))

    def test_sum_before_rounding(self):
        self.assertEqual(invoice_total([("0.005", 1), ("0.005", 1)]), Decimal("0.01"))

    def test_discount_then_tax(self):
        self.assertEqual(invoice_total([("100", 1)], discount="0.10", tax="0.06"), Decimal("95.40"))

