import unittest
from decimal import Decimal
from solution import invoice_total

class HiddenTests(unittest.TestCase):
    def test_no_rounding_before_discount(self):
        self.assertEqual(invoice_total([("0.045", 1)], discount="0.5"), Decimal("0.02"))

    def test_half_up_final_rounding(self):
        self.assertEqual(invoice_total([("1.005", 1)]), Decimal("1.01"))
        self.assertEqual(invoice_total([("0.335", 3)]), Decimal("1.01"))

    def test_empty_zero_and_full_discount(self):
        for lines, discount in (([], "0"), ([("99.99", 0)], "0"), ([("99.99", 2)], "1")):
            result = invoice_total(lines, discount=discount)
            self.assertIsInstance(result, Decimal)
            self.assertEqual(str(result), "0.00")

    def test_invalid_values(self):
        for lines, kwargs in (([("-1", 1)], {}), ([("1", -1)], {}), ([], {"discount": "1.1"}), ([], {"discount": "-0.1"}), ([], {"tax": "-0.1"})):
            with self.subTest(lines=lines, kwargs=kwargs), self.assertRaises(ValueError):
                invoice_total(lines, **kwargs)
